"""
素集合データ構造 (Union-Find / DSU) & ポテンシャル付きUnion-Find
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【DSU (通常版)】
- leader(a): 代表元 (根) を取得
- merge(a, b): 集合を統合
- same(a, b): 同じ集合に属するか判定
- size(a): 属する集合の要素数を取得
- groups(): 全連結成分のリストを取得

【PotentializedDSU (重み付き / ポテンシャル付き)】
- merge(x, y, w): weight(y) - weight(x) = w となるように統合 (矛盾時は False)
- diff(x, y): weight(y) - weight(x) を返す (非連結時は None)
"""

# https://github.com/ddfkit/acsampl/blob/main/dsu_.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class DSU:
    def __init__(self,n):self.p=[-1]*n
    def leader(self,a):
        p=self.p
        while p[a]>=0:
            if p[p[a]]>=0:p[a]=p[p[a]]
            a=p[a]
        return a
    def merge(self,a,b):
        x,y=self.leader(a),self.leader(b)
        if x==y:return x
        if -self.p[x]<-self.p[y]:x,y=y,x
        self.p[x]+=self.p[y];self.p[y]=x;return x
    def same(self,a,b):return self.leader(a)==self.leader(b)
    def size(self,a):return -self.p[self.leader(a)]
    def groups(self):
        res=[[] for _ in range(len(self.p))]
        for i in range(len(self.p)):res[self.leader(i)].append(i)
        return [g for g in res if g]

# https://github.com/ddfkit/acsampl/blob/main/dsu_.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class PotentializedDSU:
    def __init__(self,n):self.p=[-1]*n;self.w=[0]*n
    def leader(self,x):
        st=[]
        while self.p[x]>=0:st.append(x);x=self.p[x]
        while st:
            u=st.pop()
            self.w[u]+=self.w[self.p[u]];self.p[u]=x
        return x
    def diff(self,x,y):
        if not self.same(x,y):return None
        return self.w[y]-self.w[x]
    def same(self,x,y):return self.leader(x)==self.leader(y)
    def merge(self,x,y,w):
        rx,ry=self.leader(x),self.leader(y)
        if rx==ry:return self.diff(x,y)==w
        nw=w+self.w[x]-self.w[y]
        if -self.p[rx]<-self.p[ry]:rx,ry=ry,rx;nw=-nw
        self.p[rx]+=self.p[ry];self.p[ry]=rx;self.w[ry]=nw;return True

if __name__ == "__main__":
    dsu = DSU(5)
    dsu.merge(0, 1); dsu.merge(2, 3); dsu.merge(1, 3)
    assert dsu.same(0, 2) and dsu.size(0) == 4
    assert len(dsu.groups()) == 2

    pdsu = PotentializedDSU(4)
    pdsu.merge(0, 1, 3)
    pdsu.merge(1, 2, 5)
    assert pdsu.diff(0, 2) == 8
    assert pdsu.diff(2, 0) == -8
    print("dsu_.py: tests passed!")
